function zigzagLevelOrder(root: TreeNode | null): number[][] {
  const result: number[][] = [];
  if (root === null) return result;

  // Текущий уровень всегда храним в обычном порядке: слева направо
  let level: TreeNode[] = [root];
  let leftToRight = true;

  while (level.length > 0) {
    const values: number[] = new Array(level.length);
    const next: TreeNode[] = [];

    for (let i = 0; i < level.length; i++) {
      const node = level[i];
      // Пишем значение сразу на нужное место: с начала или с конца
      const pos = leftToRight ? i : level.length - 1 - i;
      values[pos] = node.val;

      // Детей собираем всегда слева направо — порядок обхода не меняется
      if (node.left !== null) next.push(node.left);
      if (node.right !== null) next.push(node.right);
    }

    result.push(values);
    // Следующий уровень выводим в обратном направлении
    leftToRight = !leftToRight;
    level = next;
  }

  return result;
}

// Время: O(n) — каждый узел обрабатывается один раз
// Память: O(w) — максимальная ширина уровня (не считая ответа)
